<?php
declare(strict_types=1);require dirname(__DIR__).'/bootstrap.php';use App\Core\Database;use App\Services\LiveDisplaySessionService;$pdo=Database::connection();$token=trim((string)($_GET['token']??''));$s=LiveDisplaySessionService::byToken($pdo,$token);$pagedTypes=['competitors','callbacks','finalists','heats_scores'];if(!$s||!$s['auto_page']||!in_array($s['screen_type'],$pagedTypes,true)){http_response_code(204);exit;}$test=$s['data_mode']==='test';$entryTable=$test?'bdc_test_scoring_entries':'bdc_scoring_entries';$resultTable=$test?'bdc_test_scoring_results':'bdc_scoring_results';$roleCounts=['leader'=>0,'follower'=>0];$usesActiveEntries=in_array($s['screen_type'],['competitors','heats_scores'],true);$q=$pdo->prepare($usesActiveEntries?"SELECT dance_role,COUNT(*) total FROM {$entryTable} WHERE round_id=:r AND entry_status='active' GROUP BY dance_role":"SELECT se.dance_role,COUNT(*) total FROM {$resultTable} sr JOIN {$entryTable} se ON se.id=sr.entry_id WHERE sr.round_id=:r AND sr.result_status IN('callback','alternate') GROUP BY se.dance_role");$q->execute(['r'=>$s['current_round_id']]);foreach($q->fetchAll() as $row){$role=(string)($row['dance_role']??'');if(isset($roleCounts[$role]))$roleCounts[$role]=(int)$row['total'];}$roleCapacity=$s['screen_type']==='heats_scores'?12:15;$pages=max(1,(int)ceil(max($roleCounts)/$roleCapacity));$next=((int)$s['page_number']%$pages)+1;$pdo->prepare("UPDATE bdc_live_display_sessions SET page_number=:p,state_version=state_version+1,updated_at=NOW() WHERE id=:id")->execute(['p'=>$next,'id'=>$s['id']]);http_response_code(204);
